@Composable fun LeadsScreen(initialLeadId:String?=null,onInitialLeadConsumed:()->Unit={},onCheckIn:(LeadSummary)->Unit={},vm:LeadsViewModel=viewModel()){
 val state=vm.state.collectAsStateWithLifecycle().value;var selectedStage by remember{mutableStateOf<LeadStage?>(null)};var appliedStage by remember{mutableStateOf<LeadStage?>(null)};var stageMenu by remember{mutableStateOf(false)};var followLead by remember{mutableStateOf<LeadSummary?>(null)};var transitionLead by remember{mutableStateOf<LeadSummary?>(null)};var deleteLead by remember{mutableStateOf<LeadSummary?>(null)}
