  item{Text("Leads",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=SalesInk);HorizontalDivider(Modifier.padding(top=8.dp,bottom=10.dp),color=SalesLine);LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){item{SummaryChip("All Leads",state.leads.size,appliedStage==null){selectedStage=null;appliedStage=null}};items(LeadStage.entries){s->SummaryChip(stageLabel(s),state.leads.count{it.stage==s},appliedStage==s){selectedStage=s;appliedStage=s}}};Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Box(Modifier.weight(1f)){OutlinedButton({stageMenu=true},Modifier.fillMaxWidth()){Text(selectedStage?.let(::stageLabel)?:"All stages",Modifier.weight(1f));Text("⌄")};DropdownMenu(stageMenu,{stageMenu=false}){DropdownMenuItem({Text("All stages")},{selectedStage=null;stageMenu=false});LeadStage.entries.forEach{s->DropdownMenuItem({Text(stageLabel(s))},{selectedStage=s;stageMenu=false})}}};Button({appliedStage=selectedStage}){Text("Filter")}};state.message?.let{Spacer(Modifier.height(8.dp));MessageBanner(it,vm::clear)}}
  if(visible.isEmpty())item{OutlinedCard(Modifier.fillMaxWidth()){Box(Modifier.fillMaxWidth().padding(24.dp)){Text("No leads in this stage.",color=SalesMuted)}}}
  LeadStage.entries.filter{appliedStage==null||it==appliedStage}.forEach{pipelineStage->val stageLeads=visible.filter{it.stage==pipelineStage};item(key="heading-$pipelineStage"){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(stageLabel(pipelineStage),style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold,color=SalesInk);Text(stageLeads.size.toString(),color=SalesMuted)}};items(stageLeads,key={it.id}){lead->LeadCard(lead,state.busy,onFollowUp={followLead=lead},onCheckIn={onCheckIn(lead)},onTransition={transitionLead=lead},onDelete={deleteLead=lead})}}
